def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                 hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    if not isinstance(n, int) or n < -1:
        raise ValueError("Invalid value for n, must be an integer >= -1")
    if not isinstance(qid, int) or qid < -1:
        raise ValueError("Invalid value for qid, must be an integer >= -1")

    # Map any provided hooks to functions:
    dehydration_hooks = {
        k: None if v is None else (dehydrate_object if v is True else v) for k, v in dehydration_hooks.items()
    }
    hydration_hooks = {
        k: None if v is None else v for k, v in hydration_hooks.items()
    }

    # Build up the DISCARD message:
    discard_message = "{}.discard".format(self.process_name)
    if n != -1:
        discard_message = "{}({})".format(discard_message, n)
    if qid != -1:
        discard_message = "{}({})".format(discard_message, qid)

    # Construct a RPC call:
    rpc_call = packstream.construct(
        discard_message,
        {
            "args": tuple(),
            "kwargs": {
                "n": n,
                "qid": qid,
            },
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks,
            "handlers": handlers,
        },
    )

    # Send the DISCARD message:
    return self.cypher_query(query=query, parameters=parameters, rpc_call=rpc_call, auto_commit=auto_commit)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None, db=None,
           imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
        # Define the message type
        message_type = "Begin"

        # Set the default parameters
        if mode is None:
            mode = "WRITE"
        if bookmarks is None:
            bookmarks = []
        if metadata is None:
            metadata = {}
        if timeout is None:
            timeout = self.DEFAULT_TIMEOUT
        if db is None:
            db = "graph.db"
        if imp_user is None:
            imp_user = self.DEFAULT_USER
        if dehydration_hooks is None:
            dehydration_hooks = {}
        if hydration_hooks is None:
            hydration_hooks = {}

        # Validate the parameters
        if mode not in ("READ", "WRITE"):
            raise ValueError("Invalid mode: {}".format(mode))
        if not isinstance(bookmarks, list):
            raise ValueError("Bookmarks must be a list, not {}".format(type(bookmarks)))
        if not isinstance(metadata, dict):
            raise ValueError("Metadata must be a dict, not {}".format(type(metadata)))
        if not isinstance(timeout, int):
            raise ValueError("Timeout must be an int, not {}".format(type(timeout)))
        if not isinstance(db, str):
            raise ValueError("DB must be a string, not {}".format(type(db)))
        if not isinstance(imp_user, str):
            raise ValueError("Imp_user must be a string, not {}".format(type(imp_user)))
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("Dehydration_hooks must be a dict, not {}".format(type(dehydration_hooks)))
        if not isinstance(hydration_hooks, dict):
            raise ValueError("Hydration_hooks must be a dict, not {}".format(type(hydration_hooks)))

        # Create the message
        message = Message(message_type, parameters={"mode": mode, "bookmarks": bookmarks,
                                                    "metadata": metadata, "timeout": timeout,
                                                    "db": db, "imp_user": imp_user})

        # Process the message
        response = self.process_message(message, dehydration_hooks=dehydration_hooks,
                                        hydration_hooks=hydration_hooks, **handlers)

        return response

def round_half_to_even(n):
    """
    Round half to even

    :param n: number to round
    :return: rounded number
    """
    if n % 2 == 0:
        return int(n)
    else:
        return int(n) + 1

