def shuffled(list):
    """
    Deterministically shuffle
    """
    if not isinstance(list, list):
        raise TypeError("Expected list, but received " + str(type(list)))
    shuffled_list = []
    for i in range(len(list)):
        shuffled_list.append(list.pop(i))
    return shuffled_list

