def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def wrapper(func):
        lru_cache = RecentlyUsedContainer(maxsize=maxsize)
        @wraps(func)
        def inner(*args, **kwargs):
            k = (args, frozenset(kwargs.items())) if typed else tuple(args)
            try:
                return lru_cache[k]
            except KeyError:
                pass
            v = func(*args, **kwargs)
            lru_cache[k] = v
            return v
        return inner
    return wrapper

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    from unstdlib.standard.collections_ import RecentlyUsedContainer

    container = RecentlyUsedContainer(maxsize)

    def decorator(fn):
        def wrapped(*args, **kwargs):
            key = container.get_key(*args, **kwargs)

            if key in container:
                container[key].refresh()
                return container[key]
            else:
                # Cache miss
                container[key] = fn(*args, **kwargs)
                return container[key]

        return wrapped

    @classmethod
    def memoized_call(obj, fn, cache, *args, **kwargs):
        key = container.get_key(*args, **kwargs)

        if key in container:
            container[key].refresh()
            return container[key]
        else:
            # Cache miss
            container[key] = fn(*args, **kwargs)
            return container[key]

    return decorator

