def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves up to `maxsize` results based on a Least Frequently Used (LFU) algorithm.

    """

    class LFUCache:
        def __init__(self, maxsize):
            self.maxsize = maxsize
            self.frequencies = {}
            self.cache = {}

        def __getitem__(self, key):
            frequencies = self.frequencies[key]
            self.frequencies[key] = frequencies + 1
            if frequencies == self.maxsize:
                self.evict(key)

        def __setitem__(self, key, value):
            frequencies = self.frequencies[key] = 0
            if frequencies == self.maxsize:
                self.evict(key)
            self.cache[key] = value

        def __contains__(self, key):
            return key in self.cache

        def clear(self):
            self.frequencies.clear()
            self.cache.clear()

        def evict(self, key):
            frequencies = self.frequencies.pop(key)
            self.cache.pop(key)
            if frequencies == 1:
                return
            else:
                for k in self.frequencies:
                    if self.frequencies[k] == frequencies - 1:
                        frequencies = self.frequencies[k]
                        self.frequencies[k] = frequencies + 1
                        self.frequencies[key] = frequencies + 1
                        break

    cache = LFUCache(maxsize)

    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            else:
                value = fn(*args, **kwargs)
                cache[key] = value
                return value
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = None
        hit_count = {}
        miss_count = {}

        def wrapper(*args, **kwargs):
            if cache is None:
                cache = _LFUCache(maxsize)
                hit_count = {}
                miss_count = {}

            key = _hashkey(*args, **kwargs)
            if key in cache:
                hit_count[key] += 1
                return cache[key]
            else:
                miss_count[key] += 1

            # If cache is full, remove the least frequently used key
            if len(cache) == maxsize:
                least_frequent_key = min(hit_count, key=hit_count.get)
                del cache[least_frequent_key]
                del hit_count[least_frequent_key]
                del miss_count[least_frequent_key]

            # Add new key to cache
            v = func(*args, **kwargs)
            cache[key] = v
            hit_count[key] = 1
            miss_count[key] = 0
            return v

        return wrapper

