def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.

    Args:
        e: Any exception instance.
        max_level: Maximum call stack level (default 30)
        max_path_level: Maximum path level (default 5)

    Returns: The exception readable string.

    """
    exception_name = type(e).__name__
    details = "".join(["{} - {}".format(type(e).__name__, e)])
    try:
        exception_path = "".join(["exception_path: {}".format(e.args)])
    except:
        exception_path = "(an exception occurred when attempting to extract the exception path)"

    call_stack = []
    number = 0
    total frame = -1
    limit_reached = False
    try:
        for frame in inspect.getinnerstack(e, context=5):
            if number == 0:
                total_frame = inspect.getframe(frame)
            if limit_reached:
                break
            if number == max_level:
                limit_reached = True
                break
            try:
                code = str(inspect.getsource(total_frame).get_text())
            except:
                code = "<error retrieving code>"
            try:
                file, line = inspect.getframe(frame).f_code.co_filename, inspect.getframe(frame).f_lineno
            except:
                file, line = "?", "?"
            try:
                args = ", ".join(frame.f_locals.values())
            except:
                args = "<error retrieving arguments>"
            call_stack.append("{}. {}: {}; file: {}; line: {}; args: {}".format(number, exception_name, details, file, line, args))
            number += 1
    except:
        call_stack = "(an exception occurred when attempting to retrieve the call stack)"

    return "Exception {}{}{}{}".format(exception_name, details, exception_path, call_stack)

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    if not isinstance(text_buffer, str):
        raise TypeError("'text_buffer' must be a string")
    if not isinstance(encoding, str):
        raise TypeError("'encoding' must be a string")
    if not isinstance(overwrite, bool):
        raise TypeError("'overwrite' must be a boolean")

    # Check if the file exists
    file_path = Path(file_name)
    if not file_path.is_file():
        if not overwrite:
            raise FileExistsError(f"File {file_name} does not exist and 'overwrite' is set to False")
        file_path.touch()

    # Open the file in the specified encoding
    with open(file_name, "a", encoding=encoding) as file:
        # Write the text buffer to the file
        file.write(text_buffer)
        return len(text_buffer)

