def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    :param classes: list of base classes
    :type classes: list
    :return: the ordered minimum equivalent of the given list of base classes
    :rtype: list
    """
    if not classes:
        return classes
    seen = set()
    result = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            result.append(cls)
    for cls in result:
        for base in cls.__bases__:
            if base not in seen:
                seen.add(base)
                result.append(base)
    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    :param classes: list of base classes
    :return: list of base classes, ordered according to the lowest possible subsumption
    """
    # create a dictionary of classes and their parents
    parent_dict = {}
    for i in range(len(classes)):
        parent_dict[classes[i]] = classes[i].__bases__

    # create a set to store the ordered classes
    ordered_classes = set()

    # iterate through the dictionary and add classes to the set
    while len(parent_dict) > 0:
        # find the class with no parents
        class_no_parents = None
        for k, v in parent_dict.items():
            if not v:
                class_no_parents = k
                break

        # add the class to the set and remove it from the dictionary
        ordered_classes.add(class_no_parents)
        parent_dict.pop(class_no_parents)

        # for each parent of the newly added class, remove the parent from the dictionary
        for k, v in parent_dict.items():
            if class_no_parents in v:
                parent_dict[k].remove(class_no_parents)

    return list(ordered_classes)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    priority_que = []

    for cls in classes:
        if cls not in seen:
            priority_que.append(cls)
            seen.add(cls)

    while priority_que:
        cls = priority_que.pop(0)
        yield cls
        for b in cls.__bases__:
            if b not in seen:
                priority_que.append(b)
                seen.add(b)

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface.

    Args:
        all (bool, optional): Include attributes from all interfaces. Defaults to False.

    Returns:
        list[tuple]: List of tuples containing attribute names and descriptions.
    """
    if all:
        interface_names = [
            cls.__name__ for cls in mro(self.__class__)
            if issubclass(cls, Interface)
        ]
    else:
        interface_names = [self.__class__.__name__]

    names_and_descriptions = []
    for interface_name in interface_names:
        interface = getattr(mro(self.__class__), interface_name)(self)
        for name, description in interface.__dict__.items():
            if not name.startswith('_'):
                names_and_descriptions.append((name, description))

    return names_and_descriptions

def namesAndDescriptions(self, all=False):
    """
    Return attribute names and descriptions defined by interface.

    Args:
        all (bool): If True, include documentation from all methods and
            attributes, not just the interface.

    Returns:
        list: List of tuples of the form (name, description) if all=False, or
            list of tuples of the form (name, description, current value)
    """

    # Get a list of all attribute names defined by the interface
    interface_attributes = [
        name for name, value in self.__dict__.items() if not name.startswith('_')
    ]

    # Get a list of all methods defined by the interface
    interface_methods = [
        name for name, value in self.__dict__.items()
        if callable(value) and not name.startswith('_')
    ]

    # Get a list of all attributes and methods defined by the class
    all_attributes = [
        name for name, value in self.__dict__.items()
        if not name.startswith('_')
    ]

    # Get a list of all descriptions for the interface attributes
    interface_attribute_descriptions = []
    if not all:
        for attribute_name in interface_attributes:
            attribute = getattr(self, attribute_name)
            if attribute.__doc__:
                interface_attribute_descriptions.append(
                    (attribute_name, attribute.__doc__)
                )

    # Get a list of all descriptions for the interface methods
    interface_method_descriptions = []
    if not all:
        for method_name in interface_methods:
            method = getattr(self, method_name)
            if method.__doc__:
                interface_method_descriptions.append((method_name, method.__doc__))

    # Get a list of all descriptions for all attributes and methods
    all_attribute_descriptions = []
    if all:
        for attribute_name in all_attributes:
            attribute = getattr(self, attribute_name)
            if attribute.__doc__:
                all_attribute_descriptions.append(
                    (attribute_name, attribute.__doc__, None)
                )

        for method_name in all_attributes:
            method = getattr(self, method_name)
            if method.__doc__:
                all_attribute_descriptions.append(
                    (method_name, method.__doc__, None)
                )

    # Combine the descriptions for the interface attributes and methods
    # with the descriptions for all attributes and methods, if desired
    descriptions = (
        interface_attribute_descriptions + interface_method_descriptions +
        all_attribute_descriptions
    )

    # Return the result
    return descriptions

