def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}

    result = {}
    for k, v in d1.items():
        if k not in d2:
            result[k] = v
        elif isinstance(v, dict) and isinstance(d2[k], dict):
            v1 = difference(v, d2[k], level - 1)
            if v1:
                result[k] = v1

    return result

def find_difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    if level == 0:
        result = {}
        for k, v in d1.items():
            if k not in d2 or v != d2[k]:
                result[k] = v
        return result

    else:
        result = {}
        for k, v in d1.items():
            if k not in d2 or v != d2[k]:
                result[k] = v
            elif isinstance(v, dict):
                result[k] = find_difference(v, d2[k], level-1)
        return result

def difference(d1, d2, level=-1):
    if level == 0:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        res = {}
        for k, v in d1.items():
            if k in d2:
                if isinstance(v, dict) and isinstance(d2[k], dict):
                    res[k] = difference(v, d2[k], level-1)
                elif v != d2[k]:
                    res[k] = v
            else:
                res[k] = v
        return res

def difference(d1, d2, level=-1):
    result = {}
    for k, v in d1.items():
        if k not in d2 or (
            level >= 0 and type(v) == dict and differ(v, d2[k], level - 1)
        ):
            result[k] = v
    return result

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.
    """
    if level == -1:
        for key in d1:
            if key not in d2:
                d1.update({key: d1[key]})
            elif type(d1[key]) == dict and type(d2[key]) == dict:
                d1[key] = difference(d1[key], d2[key], level)
    else:
        for key in d1:
            if key not in d2:
                d1[key] = d1[key]
            elif type(d1[key]) == dict and type(d2[key]) == dict:
                d1[key] = difference(d1[key], d2[key], level-1)
    return d1

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord[0] < 0 or coord[0] >= self.num_bins[0]:
        return
    if coord[1] < 0 or coord[1] >= self.num_bins[1]:
        return
    self.histogram[coord[0], coord[1]] += weight

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self._closed:
        raise ValueError("Cannot fill a closed histogram")
    if not self._events.issymmetric():
        raise TypeError("Can only fill a symmetric histogram")
    if coord.ndim != 1:
        raise ValueError("Coordinates must be one-dimensional")
    if weight <= 0:
        raise ValueError("Weight must be positive")

    for i in range(coord.size):
        x = coord[i]
        if x < self._left or x >= self._right:
            continue
        index = int(np.searchsorted(self._edges, x) - 1)
        self._events[index, :] += weight

def validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

    Examples:
        labels = {
            "key1": "valid",
            "key2": ["invalid"],
            "$$": "invalid",
            True: True,
        }
        try:
            validate_labels(labels)
        except ValidationError as err:
            assert err.messages == [
                {"['invalid']": 'expected string or bytes-like object'},
                {'$$': "Label key '$$' does not match the regex [...]"},
                {'True': 'expected string or bytes-like object'},
                {'True': 'expected string or bytes-like object'},
            ]
    """
    if not isinstance(labels, dict):
        raise TypeError("Labels must be a dictionary.")
    error_messages = []
    for label_key, label_value in labels.items():
        if not isinstance(label_key, str):
            error_messages.append(
                {"key": repr(label_key), "value": "expected string or bytes-like object"}
            )
        if not label_key.isidentifier():
            error_messages.append(
                {"key": label_key, "value": "Label key must be a valid Python identifier."}
            )
        if not label_key.isprintable():
            error_messages.append(
                {"key": label_key, "value": "Label key must be a printable string."}
            )
        if not label_key.startswith("$"):
            error_messages.append(
                {
                    "key": label_key,
                    "value": "Label key must start with a dollar sign '$$'.",
                }
            )
        if not label_key.isascii():
            error_messages.append(
                {"key": label_key, "value": "Label key must be an ASCII string."}
            )
        if len(label_key) > 255:
            error_messages.append(
                {
                    "key": label_key,
                    "value": "Label key must not exceed 255 characters.",
                }
            )
        if not isinstance(label_value, str):
            error_messages.append(
                {"key": label_value, "value": "expected string or bytes-like object"}
            )
        if not label_value.isascii():
            error_messages.append(
                {"key": label_value, "value": "Label value must be an ASCII string."}
            )
        if len(label_value) > 255:
            error_messages.append(
                {"key": label_value, "value": "Label value must not exceed 255 characters."}
            )
    if error_messages:
        raise ValidationError(error_messages)

def validate_key(key):
    pattern = re.compile("[a-z0-9]{40}")
    if not pattern.match(key):
        raise ValidationError("Key must be a string of length 40 and only contain lowercase letters and digits.")

def validate_key(key):
    """
    Validate the given key against the corresponding regular expression.
    """
    import re

    pattern = r'[a-zA-Z0-9]{8,45}'
    if re.match(pattern, key):
        return True
    else:
        raise ValidationError(f'The key {key} is not valid.')

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generates part of a default observer schema from a partial Kubernetes resource dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    """
    # If this is the first level, copy the identifying fields from the manifest dict
    if first_level:
        observer_schema = {
            "apiVersion": manifest_dict.get("apiVersion"),
            "kind": manifest_dict.get("kind"),
            "metadata": manifest_dict.get("metadata")
        }
    else:
        observer_schema = {}

    # Replace all non-list and non-dict values by None
    for key, value in manifest_dict.items():
        if not isinstance(value, (dict, list)):
            observer_schema[key] = None
            continue

        # Recursively call ourselves for dict and list values
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) for item in value]

    return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    new_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            new_dict[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            new_dict[key] = generate_default_observer_schema_list(value)
        else:
            new_dict[key] = None

    if first_level:
        for field in ["kind", "apiVersion", "metadata"]:
            new_dict[field] = manifest_dict[field]

    return new_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i, entry in enumerate(observer_schema):
        if entry["name"] not in last_applied_manifest[i] and "default" in entry:
            last_applied_manifest[i][entry["name"]] = entry["default"]
        if entry["name"] in last_applied_manifest[i] and last_applied_manifest[i][entry["name"]] is None and entry["default"] == "":
            last_applied_manifest[i][entry["name"]] = entry["default"]
        if "items" in entry and last_applied_manifest[i]["items"] is None and (last_applied_manifest[i]["items"] is None or len(last_applied_manifest[i]["items"]) == 0):
            last_applied_manifest[i]["items"] = [{k: v for k, v in entry["items"][0].items() if k != "value"} for _ in range(len(response[i]["items"]))]
        if "items" in entry and "value" in entry["items"][0] and entry["items"][0]["value"] is not None:
            for j, item in enumerate(response[i]["items"]):
                last_applied_manifest[i]["items"][j]["value"] = entry["items"][0]["value"]
        if "name" in last_applied_manifest[i] and "items" in last_applied_manifest[i] and last_applied_manifest[i]["items"] is not None and len(last_applied_manifest[i]["items"]) < len(response[i]["items"]):
            for x in range(len(response[i]["items"]) - len(last_applied_manifest[i]["items"])):
                last_applied_manifest[i]["items"].append({})
        if "name" in last_applied_manifest[i] and "items" in last_applied_manifest[i] and last_applied_manifest[i]["items"] is not None and len(last_applied_manifest[i]["items"]) > len(response[i]["items"]):
            last_applied_manifest[i]["items"] = last_applied_manifest[i]["items"][:len(response[i]["items"])]
        if entry["name"] in last_applied_manifest[i] and entry["type"] == "dict" and last_applied_manifest[i][entry["name"]] is not None:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i][entry["name"]], entry["items"], response[i][entry["name"]])
        if entry["name"] in last_applied_manifest[i] and entry["type"] == "list" and last_applied_manifest[i][entry["name"]] is not None:
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i][entry["name"]], entry["items"], response[i][entry["name"]])

def update_last_applied_manifest_list_from_resp(last_applied_manifest,
                                                               observer_schema,
                                                               response):
    for i, item in enumerate(response):
        if isinstance(item, list):
            if i >= len(last_applied_manifest):
                last_applied_manifest.append([])
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i],
                                                         observer_schema[i],
                                                         item)
        elif isinstance(item, dict):
            if i >= len(last_applied_manifest):
                last_applied_manifest.append({})
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i],
                                                         observer_schema[i],
                                                         item)
        else:
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(None)
            last_applied_manifest[i] = item

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Update partially applied `last_applied_manifest` from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): Partially applied `last_applied_manifest` being updated.
        observer_schema (list): Partially applied schema of the entity being observed.
        response (list): Partial response from the Kubernetes API.

    Note:
        The function is meant to be called recursively with the updated `last_applied_manifest`
        and the schema being applied.

    """
    for index, item in enumerate(response):
        if index >= len(last_applied_manifest):
            last_applied_manifest.append(item)
        else:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[index], observer_schema[index], item)

    for index, item in enumerate(last_applied_manifest):
        if index >= len(response):
            last_applied_manifest.pop()
        else:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[index], observer_schema[index], response[index])

    for index, item in enumerate(last_applied_manifest):
        if isinstance(item, dict):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[index], observer_schema[index], response[index])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if not last_applied_manifest or not observer_schema or not response:
        raise ValueError("last_applied_manifest, observer_schema, and response cannot be None")

    # loop through the response and fill in the missing fields in the last_applied_manifest
    for i, resp_field in enumerate(response):
        if i >= len(last_applied_manifest):
            # if the response is longer than the last_applied_manifest, append new fields
            last_applied_manifest.append(observer_schema[i])
        else:
            # if the response is shorter than the last_applied_manifest, remove extra fields
            last_applied_manifest = last_applied_manifest[:i+1]

        # update the field in last_applied_manifest with the corresponding response field
        last_applied_manifest[i]["value"] = resp_field

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Update partial last_applied_manifest from partial Kubernetes response"""
    if not last_applied_manifest:
        last_applied_manifest = {}
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field_name in observer_schema["observed_fields"]:
        if field_name not in response:
            raise KeyError("The observed field '{}' is not present in the Kubernetes response".format(field_name))
        last_applied_manifest[field_name] = response[field_name]
    return last_applied_manifest

def generate_default_observer_schema(app):
    for resource in app.spec.manifest.resources:
        if resource.observer_schema is None:
            resource.observer_schema = {}
            for field in resource.fields.values():
                field_type = field.type
                if isinstance(field_type, String) or isinstance(field_type, Integer):
                    resource.observer_schema[field.name] = {"type": field_type.type}
                elif isinstance(field_type, Map) and isinstance(field_type.contained_type, String):
                    resource.observer_schema[field.name] = {"type": "object", "additionalProperties": {"type": field_type.contained_type.type}}
                elif isinstance(field_type, Array) and isinstance(field_type.contained_type, String):
                    resource.observer_schema[field.name] = {"type": "array", "items": {"type": field_type.contained_type.type}}
    return app

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # extract the Kubernetes resources present in the manifest
    manifest_resources = set(map(lambda m: m.kind, app.spec.manifest))

    # iterate over the resources and check if a custom observer schema has been defined
    # for each resource
    default_observer_schema = {}
    for resource_kind in manifest_resources:
        resource_observer_schema = app.spec.observer_schema.get(resource_kind)

        # if a custom observer schema has not been defined, generate a default one
        if resource_observer_schema is None:
            default_observer_schema[resource_kind] = {
                "api_version": f"{app.spec.api_group}/v1",
                "kind": resource_kind,
                "manifest": {
                    "spec": {
                        "manifest": f"{{'kind': '{resource_kind}', 'apiVersion': '{app.spec.api_group}/v1'}}"
                    }
                }
            }

    # return the generated default observer schema
    return default_observer_schema

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes

    :param params: The set of in-style parameters.
    :type params:collections.abc.Mapping or collections.abc.Sequence

    :return: The formatted SQL query.
    :rtype: Tuple[str, Dict or List]
    """
    if self.in_style == Params.IN_STYLE_NAMED:
        converted_params = {}
        if not isinstance(params, dict):
            raise ValueError("params must be a dict")
        for name in list(params.keys()):
            converted_params["@" + name] = params[name]
    else:
        converted_params = []
        if not isinstance(params, list):
            raise ValueError("params must be a list")
        for value in range(len(params)):
            converted_params.append(value)
    return (sql.format(**converted_params), converted_params)

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple
    """
    out_style = self.params.out_style
    if out_style == "named":
        out_params = {}
        for name, value in params.items():
            out_params[name] = value
    elif out_style == "ordinal":
        out_params = []
        for value in params:
            out_params.append(value)
    else:
        raise ValueError(f"Invalid out-style: {out_style}")
    return (sql, out_params)

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple
    """
    if not isinstance(params, (dict, list)):
        raise TypeError("'params' must be a dict or a list")

    # Check if the query contains any in-style parameters
    if not any(p.startswith("?") for p in sql):
        return (sql, params)

    # Convert the in-style parameters to out-style parameters
    if isinstance(params, dict):
        params = {i: [p] for i, p in enumerate(params)}
    else:
        params = {i: p for i, p in enumerate(params)}

    # Extract the out-style parameters from the query
    out_params = re.findall(r"\?\d+", sql)

    # Replace the in-style parameters with out-style parameters in the query
    for param in out_params:
        i = int(param[1:])
        sql = sql.replace(param, ":{}".format(i), 1)

    return (sql, params)

def formatmany(self, sql, many_params):
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    :param sql: The SQL query as a string or bytes.
    :param many_params: An iterable containing each set of in-style parameters.
    :return: A tuple containing the formatted SQL query and a list containing each converted out-style parameter.
    """
    if not self.in_style:
        return sql, many_params

    formatted_sql = sql
    out_params = []
    params = []
    for in_params in many_params:
        if self.in_style == "named":
            if not isinstance(in_params, Mapping):
                raise ValueError("In-style parameters must be a mapping in a named parameter style")
            for key, value in in_params.items():
                params.append(key + "=" + self.param_style.format(value))
        elif self.in_style == "ordinal":
            if not isinstance(in_params, Sequence):
                raise ValueError("In-style parameters must be a sequence in an ordinal parameter style")
            params.extend(self.param_style.format(val) for val in in_params)
        else:
            raise ValueError("Unsupported in-style parameter style: " + self.in_style)

        if self.out_style == "named":
            for i, key in enumerate(in_params.keys()):
                placeholder = ":" + key
                out_params.append({placeholder: params[i]})
        elif self.out_style == "ordinal":
            for i, param in enumerate(params):
                placeholder = ":" + str(i + 1)
                out_params.append({placeholder: param})
        else:
            raise ValueError("Unsupported out-style parameter style: " + self.out_style)

        formatted_sql = self.sql_with_outbound_params(formatted_sql, out_params)

    return formatted_sql, out_params

