def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Check that inventory is a dict
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dict")

    # Check that the inventory contains the required fields
    required_fields = set(["name", "version", "type"])
    inventory_keys = set(inventory.keys())
    missing_fields = required_fields.difference(inventory_keys)
    if missing_fields:
        raise ValueError(f"Inventory is missing required fields: {', '.join(missing_fields)}")

    # Check that the type field is a string
    if not isinstance(inventory["type"], str):
        raise ValueError(f"Type field in inventory must be a string, got {type(inventory['type'])}")

    # Check that the type field is a valid specification version
    type_field_value = inventory["type"]
    if extract_spec_version:
        if type_field_value not in self.supported_spec_versions:
            raise ValueError(f"Unsupported specification version found: {type_field_value}")
    else:
        if type_field_value != self.spec_version:
            raise ValueError(f"Specification version mismatch: expected {self.spec_version}, got {type_field_value}")

    # Check that the version field is a string
    if not isinstance(inventory["version"], str):
        raise ValueError(f"Version field in inventory must be a string, got {type(inventory['version'])}")

    # Check that the version field is a valid semver version
    try:
        semver.VersionInfo.parse(inventory["version"])
    except ValueError as e:
        raise ValueError("Version field in inventory must be a valid semver version") from e

    # Check that the name field is a string
    if not isinstance(inventory["name"], str):
        raise ValueError(f"Name field in inventory must be a string, got {type(inventory['name'])}")

    # Check that the name field is a valid Python identifier
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", inventory["name"]):
        raise ValueError("Name field in inventory must be a valid Python identifier")

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of files in the manifest that are used
    :param digests_used: List of digests used in the app
    """
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is not present in the manifest")
    for file in manifest_files:
        if file not in digests_used:
            self.unused_files.append(file)

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The provided prior is not an InventoryValidator object.")

    if self.dimension != prior.dimension:
        raise ValueError("The dimensions of the two inventories do not match.")

    for i in range(self.dimension):
        if self.get_quantity(i) != prior.get_quantity(i):
            raise ValueError(f"The quantity at index {i} of the two inventories do not match.")

    if self.num_constrained_dims != prior.num_constrained_dims:
        raise ValueError("The number of constrained dimensions of the two inventories do not match.")

    for i in range(self.num_constrained_dims):
        if self.get_constrained_dim(i) != prior.get_constrained_dim(i):
            raise ValueError(f"The constrained dimension at index {i} of the two inventories do not match.")

    if self.get_prior_version() != prior.get_prior_version():
        raise ValueError("The prior versions of the two inventories do not match.")

    if self.get_param_array() != prior.get_param_array():
        raise ValueError("The parameters of the two inventories do not match.")

def validate_as_prior_version(self, prior):
    """ Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that prior is defined and is an InventoryValidator object
    if prior is None:
        raise ValueError("Prior object must be defined and must be an InventoryValidator object")

    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior must be an InventoryValidator object")

    # Check that all parameters and species in prior are also in the current inventory
    for param in prior.parameters:
        if param not in self.parameters:
            raise ValueError(f"Prior parameter {param} not found in current inventory")

    for species in prior.species:
        if species not in self.species:
            raise ValueError(f"Prior species {species} not found in current inventory")

    # Check that the stoichiometry matrix in prior is also in the current inventory
    if prior.stoichiometry_matrix is not None:
        prior_stoichiometry_matrix = prior.stoichiometry_matrix.copy()
        for row in prior.stoichiometry_matrix:
            if row.any() and any(row.cells[species] for species in prior.species):
                prior_stoichiometry_matrix.add_row(row)

        if not np.allclose(prior_stoichiometry_matrix.array, self.stoichiometry_matrix.array):
            raise ValueError("Prior stoichiometry matrix not found in current inventory")

    # Check that the propensity arrays in prior are also in the current inventory
    if prior.propensities is not None:
        for propensity in prior.propensities:
            if propensity not in self.propensities:
                raise ValueError(f"Prior propensity {propensity} not found in current inventory")

    # Check that prior constraints are also in the current inventory
    for constraint in prior.constraints:
        if constraint not in self.constraints:
            raise ValueError(f"Prior constraint {constraint} not found in current inventory")

