            raise ValueError("The propensity of reaction '{}' in 'self' is outside the allowable range of prior".format(reaction))

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for file in inventory['files']:
        if file['version'] == version:
            logical_path = file['logical_path']
            content_files = set()
            for content_file in inventory['files']:
                if content_file['logical_path'] == logical_path:
                    content_files.add(content_file)
            logical_path_map[logical_path] = content_files
    return logical_path_map

def get_logical_path_map(inventory, version):
    """
    Returns a dictionary: logical_path_in_state -> set(content_files)
    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        try:
            if item['version'] == version:
                for logical, physical in item['logical_paths'].items():
                    if logical not in logical_path_map:
                        logical_path_map[logical] = {physical}
                    else:
                        logical_path_map[logical].add(physical)
        except KeyError:
            pass
    return logical_path_map

def get_logical_path_map(inventory, version):
    """
