    :param inventory: The inventory to use.
    :param version: The version to use.
    :return: A dictionary: logical_path_in_state -> set(content_files).
    """

    logical_path_map = {}
    for file in inventory:
        if file.version == version:
            logical_path_map[file.logical_path] = file.content_files

