    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in later versions than the version being described.
    """

    logical_path_map = {}

    for content_file in inventory.content_files:
        if content_file.version == version:
            for content_path in content_file.content_paths:
                if content_path.state_path in logical_path_map:
                    logical_path_map[content_path.state_path].add(content_file)
                else:
                    logical_path_map[content_path.state_path] = {content_file}

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check the structure of the fixity block
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block should be a dictionary")

    for file_name, hashes in fixity.items():
        if not isinstance(hashes, dict):
            raise ValueError("Fixity hashes should be a dictionary")

        for hash_type, hash_value in hashes.items():
            if hash_type not in ("md5", "sha256"):
                raise ValueError("Unknown hash type {}".format(hash_type))

            if not isinstance(hash_value, str):
                raise ValueError("Hash value should be a string")

    # Make sure all files in the manifest are referenced in the fixity block
    for file_name in manifest_files:
        if file_name not in fixity:
            raise ValueError("Fixity block is missing hash information for file {}".format(file_name))

    return fixity

