                    tree = etree.parse(xml_file)
                    root = tree.getroot()
                    for child in root:
                        data[child.tag] = child.text
                except Exception as e:
                    raise RuntimeError(f"Failed to parse file {filepath}. Error: {e}")
                file_data[basename] = data
    return file_data

def _evaluate_file(prefix, file_path):
    """
    Identifies the type of file of the package: `asset` or `rendition`.

    Identifies the type of file of the package and updates packages with the type and
    the address of the file being analyzed.

    Parameters
    ----------
    prefix : str
        filename without extension
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    type_map = {
        "asset": {
            "extension": ".pzip",
            "folder": "assets"
        },
        "rendition": {
            "extension": ".rend",
            "folder": "renditions"
        }
    }

    for package_type in type_map.keys():
        if file_path.endswith(type_map[package_type]["extension"]):
            return {
                "type": package_type,
                "path": os.path.join(file_folder, type_map[package_type]["folder"], "{}{}".format(prefix, type_map[package_type]["extension"]))
            }

    return {}

