def extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the number and supplement from the content of an <issue> element.

    :param issue: The <issue> element to extract from.
    :return: A tuple of integers, representing the number and supplement, in that order.
    """
    issue_content = issue.text.strip()

    split_content = issue_content.split()
    if len(split_content) == 1:
        return (int(split_content[0]), None)
    elif len(split_content) == 2:
        number_parts = split_content[0].split("-")
        if len(number_parts) == 1:
            return (int(number_parts[0]), int(split_content[1]))
        else:
            return (int(number_parts[0]), int(split_content[1]))
    else:
        raise ValueError("Invalid format for issue element")

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    if not issue.text:
        return (None, None)

    pattern = r"^(\d+)(?: +(Suppl|spe|Spe|s2|PR)?\.? *(\d+))?$"
    match = re.search(pattern, issue.text)
    if not match:
        return (None, None)

    number = int(match.group(1))
    suppl = match.group(2)
    suppl_number = int(match.group(3)) if match.group(3) else 1

    return (number, suppl, suppl_number)

