absorb(self, args):
    if not args:
        return None
    args = sorted(args, key=operator.attrgetter("op"), reverse=True)
    targets = []
    sources = []
    for a in args:
        if a.op.is_intersection:
            sources.append(a.lhs)
            targets.append(a.rhs)
        else:
            targets.append(a.lhs)
    targets = set(targets)
    for s in sources:
        if s in targets:
            targets.remove(s)
            targets.add(s.get_complement())
    return [a.get_absorbed() if a.lhs in targets else a.get_and_complemented()
for a in args]

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.

    :return:
        A timezone-aware :class:`datetime.datetime` object in the
        ``new_timezone``, or :data:`None` if the input was naive.
    """
    # We don't care about the input timezone, so just use the system TZ for these calculations
    system_tz = get_default_timezone()
    if not hasattr(dt, "tzinfo"):
        return None
    # If the input datetime is already in the system TZ, we don't have to do anything
    if dt.tzinfo.tzname(dt) == system_tz.tzname(dt):
        return dt
    utc = datetime.utcfromtimestamp(mktime(dt.timetuple()))
    # If the input datetime is ambiguous (exists twice in the current TZ due to a DST transition),
    # determine if that ambiguous datetime starts or ends in a fold state and return the appropriate
    # timezone-aware datetime
    if not dt.resolves_to(utc):
        fold = dt.resolves_to_fold(utc)
        if dt.starts_resolution(utc):
            if fold:
                return system_tz.clamp(utc + timedelta(days=1), dt)
            else:
                return system_tz.localize(utc)
        elif dt.ends_resolution(utc):
            if not fold:
                return system_tz.clamp(utc, dt)
            else:
                return system_tz.localize(utc - timedelta(days=1))
    # Otherwise, our input datetime exists only once in the current TZ, so we can directly
    # localize it to the desired timezone
    return system_tz.localize(dt)

def _fromutc(self, dt):
    # Determine if the datetime is ambiguous and in a "fold" state
    if dt.tzinfo.is_ambiguous(dt):
        fold = dt.tzinfo.dst(dt)
    else:
        fold = None

    # Calculate the new datetime in the desired timezone
    result = dt.replace(tzinfo=None)
    if dt.tzinfo:
        result = result.astimezone(self.tz)

    # If the datetime was ambiguous and in a "fold" state, adjust the result accordingly
    if fold:
        result += fold

    return result

