def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if commands is None or len(commands) == 0:
        raise ValueError("No commands to run")
    if args is None or len(args) == 0:
        raise ValueError("No arguments to pass")
    if cwd is not None and not os.path.exists(cwd):
        raise ValueError("Directory does not exist")
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Commands must be strings")
    if not isinstance(args, list):
        raise ValueError("Arguments must be a list")
    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("Arguments must be strings")
    if verbose:
        print("Running command: {}".format(commands))
    if hide_stderr:
        # evaluate command in subprocess, capture output
        try:
            output = subprocess.check_output(commands, cwd=cwd, env=env)
        except subprocess.CalledProcessError as err:
            if not hide_stderr:
                # display stderr if hide_stderr is False
                print(err.output.decode("utf-8"))
            raise
    else:
        # execute command in subprocess, print output
        try:
            output = subprocess.check_output(commands, cwd=cwd, env=env)
        except subprocess.CalledProcessError as err:
            print(err.output.decode("utf-8"))
            raise
    return output.decode("utf-8")

def run_command(commands: list, args: list, cwd: str = None, verbose: bool = False, hide_stderr: bool = False, env: dict = None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    try:
        if verbose:
            print(" ".join(commands), end="")
            if args:
                print(" ".join(args))
            else:
                print()

        process = subprocess.Popen(commands + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate()

        if hide_stderr and error:
            print(error.decode(), end="")
        elif verbose or error:
            print(error.decode())

        return output.decode()
    except Exception:
        print("Error running command:", commands + args)

