def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects, good_objects = 0, 0

    # Get all objects in the table
    if show_warnings:
        warnings = []
    for obj in self._db.all():
        num_objects += 1

        # Check if object is actually a dictionary
        if not isinstance(obj, dict):
            if show_warnings:
                warnings.append("Object {obj} is not a dictionary".format(obj=obj))
            continue

        # Check if object has the necessary keys
        if 'id' not in obj:
            if show_warnings:
                warnings.append("Object {obj} is missing required key 'id'".format(obj=obj))
            continue

        if 'parents' not in obj:
            if show_warnings:
                warnings.append("Object {obj} is missing required key 'parents'".format(obj=obj))
            continue

        # Check if object has the correct parent key
        for parent in obj['parents']:
            if parent not in obj:
                if show_warnings:
                    warnings.append("Object {obj} references parent {parent} that is not in its own hierarchy".format(obj=obj, parent=parent))

        # Check if object has the correct depth key
        if 'depth' not in obj:
            if show_warnings:
                warnings.append("Object {obj} missing required key 'depth'".format(obj=obj))
            continue

        if obj['depth'] < 0:
            if show_warnings:
                warnings.append("Object {obj} has depth {depth} which is negative".format(obj=obj, depth=obj['depth']))
            continue

        # Check if object's children are correct
        if validate_objects:
            children = [c['id'] for c in self._db[obj['id']]['children']]
            for child in children:
                if child not in obj['children']:
                    if show_warnings:
                        warnings.append("Object {obj} refers to missing child {child}".format(obj=obj, child=child))
                    continue
        good_objects += 1

    # Check if all objects are stored with a consistent hash
    # Technically, this is redundant with check_digests, but it's still a good check
    if check_digests:
        for id, obj in self._db.items():
            if id not in obj:
                if show_warnings:
                    warnings.append("Object {obj} is missing required key 'id'".format(obj=obj))
                continue
        good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if validate_objects:
        # Iterate over the objects in the hierarchy
        for obj in self.get_objects():
            num_objects += 1

            # If the object is not valid, print a warning
            if not obj.is_valid():
                if show_warnings:
                    print(f"WARNING: Object '{obj.get_id()}' is not valid")
            # Otherwise, print a message saying the object is good
            else:
                good_objects += 1
                if show_warnings:
                    print(f"Good: Object '{obj.get_id()}' is valid")

    if check_digests:
        # Iterate over the objects in the hierarchy
        for obj in self.get_objects():
            num_objects += 1

            # If the object is not valid, print a warning
            if not obj.check_digest():
                if show_warnings:
                    print(f"WARNING: Object '{obj.get_id()}' has a bad digest")
            # Otherwise, print a message saying the object is good
            else:
                good_objects += 1
                if show_warnings:
                    print(f"Good: Object '{obj.get_id()}' has a good digest")

    return num_objects, good_objects

def next_version(version: str) -> str:
    if version:
        if version.isdigit():
            if version[0] == '0':
                return str(int(version) + 1)
            else:
                return str(int(version) + 1).zfill(len(version))
        else:
            parts = version.split('.')
            if len(parts) < 2:
                return '1.0'
            major = int(parts[0])
            minor = int(parts[1])
            if major == 99:
                return f'0.{minor + 1}'
            else:
                return f'{major + 1}.0'

