def find_path_type(path):
    """
    Returns a string indicating the type of thing at the specified path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.

    :param path: path to a directory
    :return: string indicating the type of thing at the specified path
    """
    if not path.endswith('/'):
        path += '/'

    namaste_path = path + '0=*'

    try:
        with open(namaste_path, 'rb') as f:
            header = Namaste.parse_header(f)
            if header['type'] == Namaste.ROOT_TYPE:
                return 'root'
            elif header['type'] == Namaste.OBJECT_TYPE:
                return 'object'
            else:
                return 'file'
    except FileNotFoundError:
        return 'path-not-found'
    except Exception as e:
        return str(e)

