def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import shlex
    import subprocess

    output = []

    # Get the list of commands
    commands = ["borgmatic"]
    result = subprocess.run(["borgmatic", "--help"], capture_output=True)
    if result.returncode != 0:
        printer.error(
            "Error retrieving commands for bash completion."
        )
        return None
    for line in result.stdout.decode("utf-8").splitlines():
        if line.startswith("Usage:"):
            break
        commands.append(line.split()[0])

    # Get the list of options and arguments for each command
    for command in commands:
        cmd = shlex.split("borgmatic {} --help".format(command))
        result = subprocess.run(cmd, capture_output=True)
        if result.returncode != 0:
            printer.error(
                "Error retrieving parameters for command '{}'".format(
                    command
                )
            )
            continue
        for line in result.stdout.decode("utf-8").splitlines():
            if not line.startswith(" "):
                continue
            option = line.split()[0]
            if option[0] == "(":
                option = option[1:]
            output.append(option)
    return output

