def size_to_bytes(size):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    :param size: A string representing a human readable file size (eg: '500K')
    :return: A decimal representation of file size
    """
    size = size.upper()
    if size.endswith('B'):
        size = size[:-1]
    unit = size[-1]
    multiplier = None
    if unit == 'K':
        multiplier = 1024
    elif unit == 'M':
        multiplier = 1024 * 1024
    elif unit == 'G':
        multiplier = 1024 * 1024 * 1024
    elif unit == 'T':
        multiplier = 1024 * 1024 * 1024 * 1024
    elif unit == 'P':
        multiplier = 1024 * 1024 * 1024 * 1024 * 1024
    elif unit == 'E':
        multiplier = 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif unit == 'Z':
        multiplier = 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif unit == 'Y':
        multiplier = 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        raise ValueError(f"Invalid unit: {unit}")
    return int(float(size[:-1]) * multiplier)

