def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return alphabet[0]

    if padding is not None and number < 0:
        raise ValueError("Padding is not supported for negative numbers")

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    base = len(alphabet)
    num = abs(number)
    result = []
    while num > 0:
        result.append(alphabet[num % base])
        num //= base
    if padding is not None:
        result = [alphabet[0]] * max(0, padding - len(result)) + result
    if number < 0:
        result.append(alphabet[0])
    return ''.join(result[::-1])

