        pattern = re.compile(r'^(\s+|"(?:\\.|[^"])*?(?<!\\)"|'
                             r"\'.*?(?<!\\)\'|[^\s.'].*)")
    elif platform == '1':
        pattern = re.compile(r'^(\s+|"(?:\\.|[^"])*?(?<!\\)"|'
                             r"\'.*?(?<!\\)\'|[^\s'">,.])")
    else:
        pattern = re.compile(r'^(\s+|"(?:\\.|[^"])*?(?<!\\)"|'
                             r"\'.*?(?<!\\)\'|[^\s.]*)")

    items = []
    item = ''
    for match in pattern.finditer(s):
        item += match[0]
        if not match.group():
            items.append(item)
            item = ''

    return items

def split(s: str, platform: str = 'this') -> List[str]:
    """Multi-platform variant of shlex.split() for command-line splitting.

    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    # split using regex, which is faster than shlex
    if platform == 'this':
        platform = platform_module.__name__.endswith('posix')
    if platform == 1:
        pattern = re.compile(r"""
        (?x)                               # verbose, ignore whitespace
        (?<!\\)                            # backslash not before
        (?:
            (?:^|[^\w@% voltage"))                # not preceded by
            (?:[\w@% voltage"():,+.`~!#&$_\\/]*?)   # split on these
        )                                   # end group
        """)
        return pattern.split(s)
    elif platform == 0:
        pattern = re.compile(r"""
        (?x)                               # verbose, ignore whitespace
        (?<!\\)                            # backslash not before
        (?:
            (?:^|[^\w@"()% volume\":;!#&,+.\/\\])   # not preceded by
            (?:[\w@"()% volume\":;!#&,+.\/\\]*?)       # split on these
        )                                   # end group
        """)
        return pattern.split(s)
    else:
        raise ValueError("Unsupported platform")

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.

    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("The provided archive path does not exist")

    try:
        # Extract the archive to a temporary directory
        with tempfile.TemporaryDirectory(dir=tmp_path) as tmpdir:
            subprocess.run(["tar", "-xzf", archive_path, "-C", tmpdir])

            # Find the extracted file
            if filename is not None:
                filename = os.path.join(tmpdir, filename)
                if not os.path.exists(filename):
                    raise ValueError("The specified filename does not exist in the archive")
            else:
                try:
                    filename = next(os.path.join(tmpdir, f) for f in os.listdir(tmpdir) if os.path.isfile(os.path.join(tmpdir, f)))
                    if not os.path.exists(filename):
                        raise ValueError("The specified filename does not exist in the archive")
                except StopIteration:
                    raise ValueError("The archive does not contain any files")

            # Create a file repo with the extracted file
            file_repo = FileRepository(filename)
            repo_url = file_repo.create_url()

        return repo_url

    except subprocess.CalledProcessError:
        raise ValueError("The specified archive is not a valid tarball")

    except OSError:
        raise ValueError("The temporary directory for extracting the archive cannot be created")

    except ValueError as e:
        raise ValueError("The specified archive, filename, or tmp_path are not valid") from e

