def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    pattern = r"^(\d+)\s*(s|min|h|d|w|mo|y)$"
    match = re.match(pattern, frequency)
    if match is None:
        raise ValueError("Invalid frequency format")
    amount, unit = match.groups()
    amount = int(amount)
    if unit == "s":
        return datetime.timedelta(seconds=amount)
    elif unit == "min":
        return datetime.timedelta(minutes=amount)
    elif unit == "h":
        return datetime.timedelta(hours=amount)
    elif unit == "d":
        return datetime.timedelta(days=amount)
    elif unit == "w":
        return datetime.timedelta(weeks=amount)
    elif unit == "mo":
        return datetime.timedelta(weeks=amount*4)
    elif unit == "y":
        return datetime.timedelta(weeks=amount*52)
    else:
        raise ValueError("Invalid frequency format")

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    if isinstance(frequency, timedelta):
        return frequency
    if isinstance(frequency, str):
        m = re.match(r'^(\d+)\s*([a-z]+)$', frequency)
        if not m:
            raise ValueError("Invalid frequency: '{}'".format(frequency))
        amount = int(m.group(1))
        unit = m.group(2).lower()
        if unit not in ['days', 'weeks', 'months']:
            raise ValueError("Invalid frequency unit: '{}'".format(unit))
        return datetime.timedelta(**{unit: amount})
    raise TypeError("Unsupported frequency type: '{}'".format(type(frequency)))

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None
    m = re.match(r'^(\d+)\s*(years?|months?|weeks?|days?|hours?|minutes?|seconds?)$', frequency.strip().lower())
    if not m:
        raise ValueError('Invalid frequency format')
    count = int(m.group(1))
    unit = m.group(2)
    if unit == 'years':
        return datetime.timedelta(years=count)
    elif unit == 'months':
        return datetime.timedelta(months=count)
    elif unit == 'weeks':
        return datetime.timedelta(weeks=count)
    elif unit == 'days':
        return datetime.timedelta(days=count)
    elif unit == 'hours':
        return datetime.timedelta(hours=count)
    elif unit == 'minutes':
        return datetime.timedelta(minutes=count)
    elif unit == 'seconds':
        return datetime.timedelta(seconds=count)
    raise ValueError('Invalid frequency unit')

def parse_frequency(frequency):
