def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and overwrite is False, abort before writing anything.
    """
    config_filename = os.path.expanduser(config_filename)
    config_file_dir_name = os.path.dirname(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    else:
        try:
            os.makedirs(config_file_dir_name)
        except OSError:
            if not os.path.isdir(config_file_dir_name):
                raise
        with open(config_filename, "w") as config_file:
            config_file.write(rendered_config)
            os.chmod(config_filename, mode)

