def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    cmd = [sys.executable, '-c', func.__module__ + '.' + func.__name__]
    if args:
        cmd += args
    if extra_env:
        env = os.environ.copy()
        env.update(extra_env)
    else:
        env = None
    try:
        return subprocess.run(cmd, check=True, capture_output=True, env=env,
                              timeout=timeout)
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(e.returncode, cmd, e.output) from None
    except KeyboardInterrupt:
        raise KeyboardInterrupt from None
    except:
        raise RuntimeError('Unable to run function') from None

