def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    url_parts = urllib.parse.urlparse(image_href)
    if not url_parts.netloc:
        raise ValueError("image_href must contain a valid netloc")
    use_ssl = url_parts.scheme == "https"
    return (url_parts.path.strip("/"), url_parts.netloc, use_ssl)

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    url = urllib.parse.urlparse(image_href)
    if not url.netloc:
        raise ValueError(f"Invalid image ref '{image_href}'")
    use_ssl = url.scheme == "https"
    return (url.path.split("/")[-1], url.netloc, use_ssl)

