def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("No commands specified")

    if isinstance(commands, str):
        commands = [commands]

    if verbose:
        print(args)

    stdout = None
    stderr = None

    for cmd in commands:
        try:
            proc = subprocess.Popen(args, cwd=cwd, env=env)
            proc.communicate()
        except (subprocess.SubprocessError, TypeError):
            raise ValueError(f"Error running command: {cmd}")

        if verbose:
            print(proc.stdout.read())

        if hide_stderr:
            pass # We suppress here.

        if not verbose:
            print(proc.stdout.read())
        else:
            print(proc.stderr.read())

    return None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: the command(s) to run.
    :param args: the arguments to pass to the command(s).
    :param cwd: the working directory to run the command(s) in.
    :param verbose: whether to print verbose output.
    :param hide_stderr: whether to hide the stderr of the command(s) in the output.
    :param env: an optional dictionary of environment variables to pass to the command(s).

    :return: the output of the command(s) run, or None if ``hide_stderr`` is True.
    :rtype: str or None
    """

    if not isinstance(commands, list):
        commands = [commands]

    command_str = " ".join(commands)

    if env is not None:
        env = {key: str(value) for key, value in env.items()}

    if verbose:
        print(f"Running command: {command_str}", file=sys.stderr)

    try:
        output = subprocess.check_output(command_str, cwd=cwd, stderr=subprocess.STDOUT, shell=False, env=env)
        if verbose:
            print(f"Command output: {output.decode()}", file=sys.stderr)
        return output.decode() if output else output
    except subprocess.CalledProcessError as err:
        if hide_stderr:
            return None
        else:
            raise err

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Run the given command(s)."""

    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        if verbose:
            print(f"Running command: {command} {args}")

        process = subprocess.Popen(command, args, cwd=cwd, env=env,
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                    universal_newlines=True)

        if hide_stderr:
            process.stderr.close()

        output = process.communicate()[0]

        if verbose:
            print(output)

        if process.returncode != 0:
            raise subprocess.CalledProcessError(returncode=process.returncode,
                                                cmd=command, output=output)

        return output

