            with open(config_filename) as f:
                config = f.read()
        except FileNotFoundError:
            errors.append(f"Configuration file '{config_filename}' not found.")
            continue

        # Override any default values with supplied overrides
        if overrides:
            config = f"""
            {config}
            {overrides}
            """

        # Resolve environment variables in configuration file
        if resolve_env:
            config = config.replace('$(', '$$(')

        # Attempt to parse the configuration file as TOML
        try:
            toml_config = toml.loads(config)
        except toml.Invalid TOMLError:
            errors.append(f"Invalid TOML in configuration file '{config_filename}':\n{toml.diagnostics(config)}")
            continue

        # Attempt to parse the configuration file as YAML
        try:
            yaml_config = yaml.load(config, Loader=yaml.BaseLoader)
        except yaml.YAMLError:
            errors.append(f"Invalid YAML in configuration file '{config_filename}':\n{yaml.diagnostics(config)}")
            continue

        # Return a dict of configuration filename to parsed configuration
        configs[config_filename] = toml_config if toml_config else yaml_config

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    log_errors = []

    for filename in config_filenames:
        try:
            with open(filename) as f:
                config = toml.load(f)
                if overrides is not None:
                    config = dict(config, **overrides)
                    config["filename"] = filename
                if resolve_env:
                    config = Environment().resolve(config)
                configs[filename] = config
        except Exception as e:
            log_errors.append(logging.LogRecord("ERROR", "Config file {} could not be loaded, {}".format(filename, e)))

    return configs, log_errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configs = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as config_file:
                config = yaml.safe_load(config_file)

                if overrides:
                    config.update(overrides)

                if resolve_env:
                    config = self._resolve_env_values(config)

                self._validate_config(config_filename, config)

                configs[config_filename] = config
        except (yaml.YAMLError, FileNotFoundError) as e:
            errors.append(
                logging.LogRecord(
                    levelname='ERROR',
                    name='config',
                    pathname='__init__.py',
                    lineno=0,
                    msg=f'Error parsing config file {config_filename}: {e}',
                )
            )

    return configs, errors

