def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks \< 86400000000000):
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")
    seconds = ticks / 1000000000
    microseconds = (ticks % 1000000000) * 1000
    datetime = datetime.fromtimestamp(seconds, tz)
    datetime = datetime + timedelta(microseconds=microseconds)
    return cls(datetime)

def from_ticks(ticks, tz):
    if not (0 <= ticks < 86400000000000):
        raise ValueError(f'ticks out of range (0 <= ticks < 86400000000000): {ticks}')
    return tz.utcoffset(datetime.now()) + timedelta(microseconds=ticks)

def from_ticks(cls, ticks, tz=None):
    """
    Create a time from ticks (nanoseconds since midnight).

    :param ticks: nanoseconds since midnight
    :type ticks: int
    :param tz: optional timezone
    :type tz: datetime.tzinfo

    :rtype: Time

    :raises ValueError: if ticks is out of bounds
        (0 <= ticks < 86400000000000)
    """

    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

    if tz is None:
        return cls(int(ticks / 1000000), int(ticks % 1000000), 0)
    else:
        return cls(int(ticks / 1000000), int(ticks % 1000000), tz)

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple. If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple"""
    if protocol_version is None:
        return {(3, 5): cls.V35, (3, 1): cls.V31, (1, 0): cls.V10, (0, 9): cls.V09}
    elif isinstance(protocol_version, tuple):
        if not len(protocol_version) == 2:
            raise TypeError("Protocol version must be a 2-tuple (e.g. (3, 5))")
        if protocol_version in [cls.V35, cls.V31, cls.V10, cls.V09]:
            return {protocol_version: cls.V35}
        else:
            return {}
    else:
        raise TypeError("Protocol version must be a tuple (e.g. (3, 5))")

def protocol_handlers(protocol_version=None):
    if protocol_version is None:
        return {(3, 5): cls.protocol_handler_3_5, (3, 4): cls.protocol_handler_3_4}
    elif not isinstance(protocol_version, tuple):
        raise TypeError("'protocol_version' must be a tuple")
    elif protocol_version not in [(3, 5), (3, 4)]:
        return {}
    else:
        return {protocol_version: cls.protocol_handler_3_5 if protocol_version == (3, 5) else cls.protocol_handler_3_4}

def protocol_handlers(protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple

    """
    # handle protocol_version being undefined
    if not protocol_version:
        return {(3, 5): Handler3_5, (4, 0): Handler4_0, (4, 1): Handler4_1, (4, 2): Handler4_2}

    if len(protocol_version) != 2:
        raise TypeError(f"protocol version must be passed in a tuple of length 2, got {protocol_version}")
    protocol_start, protocol_end = protocol_version
    if protocol_start < 3 or protocol_start > 4:
        raise ValueError(f"unsupported protocol version specified: {protocol_version}")
    if protocol_end < protocol_start or protocol_end > 4:
        raise ValueError(f"unsupported protocol version specified: {protocol_version}")

    supported_versions = [(3, 5), (4, 0), (4, 1), (4, 2)]
    if protocol_start == 3 and protocol_end == 4:
        supported_versions = [(3, 5), (4, 0)]
    elif protocol_start == 4 and protocol_end == 4:
        supported_versions = [(4, 0), (4, 1), (4, 2)]

    handlers = {}
    for version in supported_versions:
        if version == protocol_version:
            handlers[version] = Handler3_5
        elif version == (4, 0):
            handlers[version] = Handler4_0
        elif version == (4, 1):
            handlers[version] = Handler4_1
        elif version == (4, 2):
            handlers[version] = Handler4_2

    return handlers

def protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        return {(3, 0): cls}
    elif not isinstance(protocol_version, tuple) or len(protocol_version) != 2:
        raise TypeError("'protocol_version' must be a tuple of length 2")
    elif protocol_version[0] == 3 and protocol_version[1] == 0:
        return {protocol_version: cls}
    else:
        return {}

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return (seq, type(seq))
    if not isinstance(seq, Sequence):
        return (tuple(seq), type(seq))
    return (seq, type(seq))

