    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, six.string_types + (bytes, bytearray)):
        # Backwards-compatible (only Python 2.7)
        result = enums.SequenceType.from_string(seq)
