def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """

    if isinstance(seq, str):
        return (seq, "string")
    elif isinstance(seq, list):
        return (seq, "list")
    elif isinstance(seq, tuple):
        return (seq, "tuple")
    elif isinstance(seq, bytes):
        return (list(seq), "bytes")
    elif isinstance(seq, bytearray):
        return (list(seq), "bytearray")
    elif bufsize is not None and isinstance(seq, Iterator):
        seq = tuple(seq)
        if isinstance(seq, str):
            return (seq, "string")
        elif isinstance(seq, list):
            return (seq, "list")
        elif isinstance(seq, tuple):
            return (seq, "tuple")
        elif isinstance(seq, bytes):
            return (list(seq), "bytes")
        else:
            return (seq, "iterator")
    else:
        return (seq, "invalid")

def scale(self, other=None):
    if other is None:
        return self._scale
    else:
        if self._scale == 0 or self._scale == None:
            raise LenaValueError("Scale is unknown")
        self._scale = other
        return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                    field_names=("x", "y"), scale=None):

    if not isinstance(hist, Histogram):
        raise ValueError("hist must be a Histogram")

    if make_value is not None and not callable(make_value):
        raise ValueError("make_value must be callable or None")

    if not isinstance(get_coordinate, str):
        raise ValueError("get_coordinate must be a string")

    if not isinstance(field_names, tuple):
        raise ValueError("field_names must be a tuple")

    if scale is not None and not isinstance(scale, Scale):
        raise ValueError("scale must be a Scale or True")

    if scale is True:
        scale = hist.scale

    if make_value is None:
        make_value = lambda bin_: hist.scale(bin_.value)

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    if len(field_names) != hist.dimension:
        raise ValueError("field_names must have the same length as hist.dimension")

    if not all(isinstance(f, str) for f in field_names):
        raise ValueError("field_names must contain only strings")

    graph = Graph(hist.dimension, make_value, scale)

    for bin in hist.bins:
        point = Point()
        for i, name in enumerate(field_names):
            setattr(point, name, make_value(bin.data[i]))
        if get_coordinate == "left":
            point = Point(x=bin.x_left, y=point)
        elif get_coordinate == "right":
            point = Point(x=bin.x_right, y=point)
        elif get_coordinate == "middle":
            point = Point(x=bin.x, y=point)
        graph += point

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid("Interface not provided")

    for method_name, method_tuple in iface.namesAndDescriptions():
        if candidate is None:
            raise Invalid("Attribute '{0}' not defined".format(method_name))
        try:
            method = getattr(candidate, method_name)
        except AttributeError:
            raise Invalid("Method '{0}' not defined".format(method_name))
        if isinstance(method_tuple, tuple):
            if method is None:
                raise Invalid("Method '{0}' not defined".format(method_name))
            arg_names, arg_types = method_tuple
            if not _same_args(method, arg_names, arg_types):
                raise Invalid("Method '{0}' has incorrect signature".format(method_name))

    for attr_name, attr_tuple in iface.namesAndDescriptions():
        if candidate is None:
            raise Invalid("Attribute '{0}' not defined".format(method_name))
        try:
            attr = getattr(candidate, method_name)
        except AttributeError:
            raise Invalid("Attribute '{0}' not defined".format(method_name))
        if isinstance(attr_tuple, tuple):
            attr_type = attr_tuple[0]
            if not isinstance(attr, attr_type):
                raise Invalid("Attribute '{0}' has incorrect type".format(method_name))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Verify that the candidate claims to implement the interface
    # unless tentative mode is enabled
    if not tentative:
        provided_by(iface, candidate)

    # Get the list of required interfaces for the given interface
    required_interfaces = get_required_interfaces(iface)

    # Verify that the candidate implements all required interfaces
    for required_interface in required_interfaces:
        required_interface.providedBy(candidate)

    # Verify that the candidate defines all required methods
    required_methods = get_required_methods(iface)
    for required_method in required_methods:
        method = getattr(candidate, required_method, None)
        if method is None:
            raise zope.interface.Invalid("Candidate does not define method '%s'" % required_method)

    # Verify that the candidate defines all required attributes
    required_attributes = get_required_attributes(iface)
    for required_attribute in required_attributes:
        attribute = getattr(candidate, required_attribute, None)
        if attribute is None:
            raise zope.interface.Invalid("Candidate does not define attribute '%s'" % required_attribute)

    # Verify that the candidate defines all required properties
    required_properties = get_required_properties(iface)
    for required_property in required_properties:
        property = getattr(candidate, required_property, None)
        if property is None:
            raise zope.interface.Invalid("Candidate does not define property '%s'" % required_property)

    # Verify that the candidate implements any required interfaces
    required_implements = get_required_implements(iface)
    if not hasattr(iface, '__provided_by__'):
        raise zope.interface.Invalid("Invalid interface provided to _verify")
    inherited_interfaces = iface.__provided_by__
    for required_interface in required_implements:
        if required_interface not in inherited_interfaces:
            raise zope.interface.Invalid("Candidate does not implement required interface")

    # Verify that the candidate defines all required methods with the correct signature
    for required_method in required_methods:
        method = getattr(candidate, required_method)
        if not hasattr(method, 'funcspec'):
            raise zope.interface.Invalid("Candidate method '%s' does not have a funcspec" % required_method)
        required_signature = required_method.signature
        if hasattr(required_signature, '__provided_by__'):
            raise zope.interface.Invalid("Invalid signature provided to _verify")
        inherited_signature = required_signature.__provided_by__
        signature_bytes = (signature(method).signature_bytes
                            if hasattr(signature(method), 'signature_bytes')
                            else signature(method).__signature_bytes__)
        for inherited_byte in signature_bytes:
            try:
                byte_object = inherited_byte.__provided_by__
                byte_signature = byte_object.signature
                if byte_signature in required_signature:
                    # Check we satisfy any attributes in the required signature
                    expected_attributes = get_attributes(byte_signature).keys()
                    actual_attributes = get_attributes(signature_bytes).keys()
                    for attribute in actual_attributes:
                        if attribute.startswith('@'):
                            # We don't care about aliases
                            continue
                        if attribute not in byte_signature and attribute in expected_attributes:
                            raise zope.interface.Invalid("Candidate method '%s' has incompatible signature: does not provide required attribute '%s'" % (required_method, attribute))
                        # Check if we have aliases here
                        if '@' in attribute:
                            attribute = attribute[1:]
                            alias = attribute.split(':')[0]
                            if alias not in byte_signature and alias in expected_attributes:
                                raise zope.interface.Invalid("Candidate method '%s' has incomopatable signature: does not provide required attribute alias '%s'" % (required_method, attribute))
                    # Check we satisfy any args
                    expected_args = get_args(byte_signature).keys()
                    actual_args = get_args(signature_bytes).keys()
                    for arg in actual_args:
                        if ':' not in arg:
                            # This is a required arg
                            if arg not in byte_signature and arg in expected_args:
                                raise zope.interface.Invalid("Candidate method '%s' has incompatible signature: does not provide required arg '%s'" % (required_method, arg))
                    # Check we satisfy any kwargs
                    expected_kwargs = get_kwargs(byte_signature).keys()
                    actual_kwargs = get_kwargs(signature_bytes).keys()
                    for key in actual_kwargs:
                        if key[1:] not in byte_signature and key[1:] in expected_kwargs:
                            raise zope.interface.Invalid("Candidate method '%s' has incompatible signature: does not provide required kwarg '%s'" % (required_method, key[1:]))
                    # Check we retrieve required args and kwargs
                    actual_locals = get_locals(signature_bytes)
                    for local in expected_args:
                        if local not in byte_signature and local not in actual_locals:
                            raise zope.interface.Invalid("Candidate method '%s' has incompatible signature: does not retrieve required arg '%s'" % (required_method, local))
                    for key in expected_kwargs:
                        if key not in byte_signature and key not in actual_locals:
                            raise zope.interface.Invalid("Candidate method '%s' has incompatible signature: does not retrieve required kwarg '%s'" % (required_method, key))
                else:
                    raise zope.interface.Invalid("Candidate method '%s' has incompatible signature: does not conform to required signature '%s'" % (required_method, inherited_signature))
            except (zope.interface.Invalid, AttributeError):
                pass

def verifyObject(iface, candidate, tentative=False):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Object does not provide interface")

    for method in iface.public_methods:
        if not hasattr(candidate, method):
            raise zope.interface.Invalid(f"Object does not implement method {method}")

        method_impl = getattr(candidate, method, None)
        if not callable(method_impl):
            raise zope.interface.Invalid(f"Object does not implement method {method} as a callable")

        iface_method = getattr(iface, method, None)
        if iface_method is None:
            raise zope.interface.Invalid(f"Method {method} in interface not found")

        iface_method_sig = inspect.signature(iface_method)
        method_sig = inspect.signature(method_impl)
        if iface_method_sig != method_sig:
            raise zope.interface.Invalid(f"Signature of method does not match interface\nExpected:\n{iface_method_sig}\nFound:\n{method_sig}")

    for attribute in iface.public_attributes:
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid(f"Object does not have attribute {attribute}")

    return True

def verify_class(iface, candidate, tentative=False):
    if tentative:
        pass # TODO: Implement tentative verification
    else:
        if not candidate:
            raise ValueError("Candidate is not an instance or class")
        if not isinstance(candidate, iface):
            raise ValueError("Candidate is not an instance of %s" % iface)
        if not candidate.implements(iface):
            raise ValueError("Candidate does not implement %s" % iface)
        if candidate.generics and not all(map(lambda x: candidate.generics[x] is None or isinstance(candidate.generics[x], x), iface.generics)):
            raise ValueError("Candidate generics do not match %s" % iface.generics)
        if candidate.methods and not all(map(lambda x: candidate.methods[x] is None or isinstance(candidate.methods[x], x), iface.methods)):
            raise ValueError("Candidate methods do not match %s" % iface.methods)
        if candidate.properties and not all(map(lambda x: candidate.properties[x] is None or isinstance(candidate.properties[x], x), iface.properties)):
            raise ValueError("Candidate properties do not match %s" % iface.properties)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if isinstance(candidate, iface):
            return True
        elif tentative:
            if getattr(candidate, '__instancecheck__', None):
                return candidate.__instancecheck__(iface)
            elif getattr(candidate, '__subclasscheck__', None):
                return candidate.__subclasscheck__(iface)
        return False
    except TypeError:
        return False

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if iface is True:
            return true_checker
        if iface is False:
            return false_checker
        checker = memoized_checker_for_type.get(iface)
        if checker is not None:
            return checker
        hashable = True
    except TypeError:
        # Exception is raised if `iface` is not hashable (e.g. a dict)
        hashable = False

    # The type checker needs to be created
    checker = _create_checker_for_type(iface)
    if hashable:
        memoized_checker_for_type[iface] = checker
    return checker

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        iface = type(iface)
    if not isinstance(candidate, iface):
        raise VerificationError("The candidate does not match the interface")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not issubclass(candidate, iface):
        return False
    if tentative:
        # If the candidate is a tentative provider, we only need to check
        # that it has the right interface in its __init__ method for now.
        # We will recursively check its parent classes later.
        return True

    # Verify that the candidate's __init__ method is valid.
    init_func = getattr(candidate, "__init__", None)
    if init_func is None:
        return False
    if not callable(init_func):
        return False

    # Check that the candidate's __init__ method has the correct number of
    # parameters.
    if len(inspect.signature(init_func).parameters) != len(iface.get_required_parameters()):
        return False

    # Check that the candidate's __init__ method has the correct parameter types.
    for param_name, param_type in iface.get_required_parameters().items():
        if param_name not in init_func:
            # The param is not in the __init__ method, so it can't be valid.
            return False
        if not issubclass(init_func.parameters[param_name].annotation, param_type):
            # The param's type is not valid, so the candidate is not a valid provider.
            return False

    # Check that the candidate's __init__ method has the correct return type.
    if not issubclass(init_func.return_annotation, iface):
        return False

    # Check that the candidate's parents are also valid providers, if it has any.
    for parent in candidate.mro()[1:]:
        if not verifyClass(iface, parent, tentative=True):
            return False

    # If none of the above checks failed, the candidate is a valid provider.
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__

    :param bases: the bases to determine metaclass for
    :param explicit_mc: an optional explicit metaclass to use
