    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")
    if default and not isinstance(default, datetime.datetime):
        raise TypeError("default must be a datetime object")
    if tzinfos and not isinstance(tzinfos, dict):
        raise TypeError("tzinfos must be a dictionary")
    if ignoretz and tzinfos:
        raise ValueError("ignoretz and tzinfos cannot be set at the same time")

    try:
        date = _parse_date(timestr, default, ignoretz, tzinfos, **kwargs)
    except ParserError as e:
        raise ParserError(f"Failed to parse {timestr}") from e

    if date is None:
        raise ParserError(f"{timestr} is not a parsable date/time string")

    return date

