def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    skip = False
    replaced_text = []
    for line in text.splitlines():
        if not skip:
            for tag in line.split():
                if tag.startswith("#"):
                    tags.add(tag.lstrip("#"))
                    if replacer:
                        replaced_tag = replacer(tag.lstrip("#"))
                        replaced_text.append(replaced_tag)
                    else:
                        replaced_text.append(tag.lstrip("#"))
                else:
                    skip = False
                    replaced_text.append(line)
        else:
            skip = False
            replaced_text.append(line)
    return tags, "\n".join(replaced_text)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """ Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    lines = text.splitlines()
    in_code_block = 0
    result = ''
    for line in lines:
        if "```" in line:
            in_code_block += 1
            continue
        if in_code_block > 0:
            in_code_block -= 1
            continue
        for word in line.split():
            if word.startswith("#"):
                try:
                    tag = word.strip().split("#")[1]
                    if replacer is not None:
                        result = result.replace(word, str(replacer(tag)))
                    else:
                        result = result.replace(word, "#" + tag)
                    tags.add(tag)
                except IndexError:
                    pass
    return tags, result

def find_tags(text: str, replacer: Optional[Callable[[str], str]] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    result = ""

    code_block = False

    for line in text.splitlines():
        if line.strip().startswith("```"):
            code_block = not code_block
        elif code_block:
            continue

        for tag in re.findall(r"#(\S+)", line):
            if replacer is not None:
                result += replacer(tag)
            else:
                result += tag
            tags.add(tag)

    return tags, result

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    from urllib.parse import urlparse

    def linkify_url(url):
        """Linkify a URL by adding attributes and returning the linkified text."""
        scheme, netloc, path, params, query, fragment = urlparse(url)
        if not scheme and not netloc:
            # The URL is a relative path
            return f'<a href="{path}">{path}</a>'
        else:
            # The URL is a full URL
            return f'<a href="{url}">{url}</a>'

    def linkify_text(text):
        """Linkify text by adding attributes and returning the linkified text."""
        return re.sub(r'(?i)\b(https?://\S+[^\s\.\,\)\]\>])', linkify_url, text)

    return linkify_text(text)

