            }

        # Parse protocols and protocol details
        protocols = []
        protocol_details = {}
        if "protocols" in document:
            for protocol_name in document["protocols"]:
                protocol_details[protocol_name] = {
                    "version": document["protocols"][protocol_name]["version"],
                    "name": document["protocols"][protocol_name]["name"],
                    "description": document["protocols"][protocol_name]["description"],
                    "service": {
                        "inbound": document["protocols"][protocol_name]["service"]["inbound"],
                        "outbound": document["protocols"][protocol_name]["service"]["outbound"],
                    },
                }
            data.append(protocol_details)

        # Parse relay details
        relay = None
        if "relay" in document:
            relay = {}

        # Parse usage details
        usage = None
        if "usage" in document:
            usage = {
                "users": {
                    "total": document["usage"]["users"]["total"],
                    "activeHalfyear": document["usage"]["users"]["activeHalfyear"],
                    "activeMonth": document["usage"]["users"]["activeMonth"],
                    "activeWeek": document["usage"]["users"]["activeWeek"],
                },
                "localPosts": document["usage"]["localPosts"],
                "localComments": document["usage"]["localComments"],
            }

        # Return NodeInfo document details
        return {
            "version": version,
            "server": server,
            "organization": organization,
            "protocols": protocols,
            "protocols_details": protocol_details,
            "relay": relay,
            "usage": usage,
        }
    except Exception as e:
        # Handle errors gracefully
        print(f"Failed to retrieve NodeInfo document: {document_path}")
        raise e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('{'):
        # Parse JSON format
        return json.loads(document)
    else:
        # Parse XRD format
        parts = []
        for line in document.splitlines():
            parts.append(line.split(' ', 1))
        return {'links': [{'rel': part[0], 'href': part[1]} for part in parts]}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        webfinger_json = json.loads(document)
        return webfinger_json
    except json.JSONDecodeError:
        # Assume old XRD format
        xml_root = ET.fromstring(document)
        namespace = "{%s}" % xml_root.tag[1:-1]
        webfinger_dict = {}
        for prop, val in xml_root.items():
            webfinger_dict[prop] = val
        for link in xml_root.findall("%slink" % namespace):
            href_attrib = link.attrib["href"]
            rel_attrib = link.attrib["rel"]
            webfinger_dict[rel_attrib] = href_attrib
        return webfinger_dict

