def list_of_file_names(settings_dirs, spec_option):
    """
    Creates a new IniType complex type

    :param settings_dirs: list of directory paths
    :param spec_option: specific file name
    :return: list of file names
    """

    file_names = []
    for settings_dir in settings_dirs:
        for root, dirs, files in os.walk(settings_dir):
            for name in files:
                if name.startswith(spec_option):
                    file_names.append(os.path.join(root, name))
