def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Load the YAML content into a dictionary
    try:
        data = yaml.safe_load(spec_content)
    except yaml.YAMLError as exc:
        raise IRValidatorException(
            f"Error loading spec content: {str(exc)}"
        ) from exc

    # Check that all required fields are present
    missing_fields = []
    for field in cls.schema:
        if "required" in field and field["required"] and cls.get(field["name"]) is None:
            missing_fields.append(field["name"])
    if missing_fields:
        raise IRValidatorException(
            f"Missing required field(s) in spec content: {', '.join(missing_fields)}"
        )

    return data

def validate_from_content(spec_content):
    """
    Validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    if spec_content is None:
        raise IRValidatorException("Spec content is missing!")

    data = yaml.load(spec_content, Loader=Loader)
    if not data:
        raise IRValidatorException("Spec content is empty!")

    required_fields = ["properties", "objects"]
    for field in required_fields:
        if data.get(field) is None:
            raise IRValidatorException(f"'{field}' is required in spec!")

    return data

def validate_from_file(yaml_file):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    data = {}
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except Exception:
        raise IRValidatorException("There was a problem parsing the file.")

    # Check for mandatory fields
    if "name" not in data:
        raise IRValidatorException("Missing 'name' field in YAML file.")
    if "version" not in data:
        raise IRValidatorException("Missing 'version' field in YAML file.")
    if "description" not in data:
        raise IRValidatorException("Missing 'description' field in YAML file.")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param dict parser_dict: the parsed dictionary representation of the specification
    """
    includes = []
    for key, value in parser_dict.items():
        if key == 'include':
            for inc in value:
                includes.append(inc)
    parser_dict['includes'] = includes

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param dict parser_dict:
    """
    if 'include-dict' in parser_dict:
        include_dict = parser_dict['include-dict']
        for key, value in iteritems(include_dict):
            parser_dict[key] = self._parse_section_to_dict(value)

def _include_groups(self, parser_dict):
    """Resolves the include group directive in the spec files.

    :param dict parser_dict:
    """
    include_groups = parser_dict.get('include')
    if include_groups is not None:
        for group_name, group in include_groups.items():
            self._include_group_helper(parser_dict, group, group_name)

def _include_groups(self, parser_dict):
    # Resolves the include dict directive in the spec files.
    include_groups = parser_dict.get('include_groups', {})
    if include_groups:
        for group, members in include_groups.items():
            # Check if the group is already defined in the parser.
            if group not in parser.choices:
                # Add the group to the parser.
                parser.add_argument_group(group)

            # Add the items to the group.
            for item in members:
                # Get the short and long names for the item.
                short_name = item.get('short_name')
                long_name = item.get('long_name')

                # Skip items that are not defined in the spec.
                if not (short_name or long_name):
                    continue

                # Add the item to the group.
                parser.add_argument(
                    short_name, long_name, item.get('action', 'store'),
                    **item.get('kwds', {})
                )
            del parser.choices[group]

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        # Check if the argument has a default value in the spec
        if arg.spec is not None:
            defaults[arg.name] = arg.spec.value
        # Check if the argument has a default value in other sources
        if arg.source is not None:
            defaults[arg.name] = arg.source.value
    return defaults

def get_spec_defaults(cls):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The resolved defaults for all arguments in the `Scheme`.
    """
    defaults = {}
    for arg in cls.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to resolve defaults for non-Option type')

        # first, check if the arg has a default value in the spec
        if arg.name in cls._spec:
            defaults[arg.name] = cls._spec[arg.name]
        else:
            # if we don't have a spec value, check if we have a default for the arg
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default
            else:
                # if we don't have a default, raise an error
                raise errors.InvalidDefaultError(
                    f'Unable to resolve default value for argument: {arg.name}.'
                )

        # if we have a dict option, resolve the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.get_spec_defaults()
                if b:
                    defaults[arg.name] = b

def get_spec_defaults(self):
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if we have a dict option, build the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_defaults()
                if b:
                    defaults[arg.name] = b
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The resolved argument defaults for the current strategy.
    """
    defaults = {}
    for arg in self.args:
        # Check if the argument has a default value in the spec
        if not isinstance(arg, DictOption):
            if arg.default is not NoDefault:
                defaults[arg.name] = arg.default
        else:
            # Get the sub-dictionary of default values for the argument
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                defaults[arg.name] = sub_defaults

    # Override defaults with any user-provided values in the spec
    spec_defaults = self.spec.get_defaults()
    for key in spec_defaults:
        if key in defaults:
            defaults[key] = spec_defaults[key]
        else:
            defaults[key] = spec_defaults[key]

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        default = None
        # Check the spec first
        if arg.name in self.spec and self.spec[arg.name] is not None:
            default = self.spec[arg.name]
        # If not found in spec, check the default value
        if default is None and arg.default is not None:
            default = arg.default
        # If not found in spec and default value, check other sources
        if default is None:
            default = arg.get_default()
        # Add to defaults dict
        if default is not None:
            defaults[arg.name] = default
    return defaults

def get_deprecated_args(self):
