def _get_conditionally_required_args(command_name,
                                                    options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required_args = []
    for arg in options_spec:
        if arg['required_when'] and arg['required_when'][0] == command_name:
            conditionally_required_args.append(arg['dest'])
    if args == None:
        return conditionally_required_args
    if conditionally_required_args == []:
        return conditionally_required_args
    else:
        req_args_dict = set(conditionally_required_args)
        passed_args_dict = set(args)
        if len(req_args_dict) >= len(passed_args_dict):
            return passed_args_dict.intersection(conditionally_required_args)

