def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments will not be
    put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
    into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
    normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    # Separate control, nested, and custom args.
    control_args = {}
    nested_args = {}
    custom_args = {}

    for key, value in args.items():
        if isinstance(value, list):
            nested_args[key] = value
        elif isinstance(value, dict):
            custom_args[key] = value
        else:
            control_args[key] = value

    return control_args, nested_args, custom_args

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    for a in args:
        if a.startswith("--"):
            if a.startswith("--_ansible_") or a.startswith("--file"):
                control_args[a] = args[a]
            elif a.startswith("--"):
                nested_args[a] = args[a]
        elif a.startswith("-"):
            # Handle short arguments
            if a in ["--", "-f", "-q", "-T", "-t"]:
                control_args[a] = args[a]
            elif a.startswith("-"):
                nested_args[a] = args[a]
    return control_args, nested_args

def get_nested_custom_and_control_args(args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('_'):
            control_args[arg[1:]] = args[arg]
        elif arg.startswith('~'):
            custom_args[arg[1:]] = args[arg]
        else:
            nested_args[arg] = args[arg]

    return control_args, nested_args, custom_args

